15: export class AgrupacionEspaciosAcademicosComponent implements OnInit {
16:   displayedColumns: string[] = ['nombre', 'descripcion', 'color'];
17:   agrupacionEspacios: AgrupacionEspacios[] = [];
18:   facultadId!: string;
19:   dataSource!: MatTableDataSource<AgrupacionEspacios>;
20: 
21:   formAgrupacion = this.fb.group({
22:     'nombre': ['', Validators.required],
23:     'codigo_abreviacion': ['', Validators.required],
24:     'descripcion': ['', Validators.required],
25:     'color_hex': ['#E0E0E0', Validators.required]
26:   })
27:   
28: 
29:   constructor(
30:     private translate: TranslateService,
31:     private fb: FormBuilder,
32:     private espaciosAcademicosService: EspaciosAcademicosService,
33:     private popUpManager: PopUpManager,
34:     private activatedRoute: ActivatedRoute,
35:     private readonly router: Router
36:   ) {}
37: 
38:   async ngOnInit() {
39:     this.activatedRoute.params.subscribe(params => {
40:       this.facultadId = params['facultad_id']
41:     })
42: 
43:     await this.cargarDatosTabla();
44:   }
45: 
46:   async cargarDatosTabla() {
47:     await this.cargarAgrupacionEspacios(this.facultadId).then((agrupacion_espacios) => {
48:       this.agrupacionEspacios = agrupacion_espacios;
49:     }).catch((error) => {
50:     })
51: 
52:     this.dataSource = new MatTableDataSource<AgrupacionEspacios>(this.agrupacionEspacios);
53:   }
54: 
55:   async cargarAgrupacionEspacios(byFacultad?: any): Promise<AgrupacionEspacios[]> {
56:     let facuId = "";
57:     if (byFacultad != undefined) {
58:       facuId = `,facultad_id:${byFacultad}`;
59:     }
60:     return new Promise<any>((resolve, reject) => {
61:       this.espaciosAcademicosService.get('agrupacion-espacios?query=activo:true' + facuId + '&limit=0').subscribe(
62:         (response: any) => {
63:           if (Object.keys(response.Data[0]).length > 0) {
64:             resolve(response.Data);
65:           } else {
66:             reject({ "agrupacion_espacios": null });
67:           }
68:         }, (err) => {
69:           reject({ "agrupacion_espacios": err });
70:         }
71:       )
72:     });
73:   }
74: 
75:   aplicarFiltro(event: Event) {
76:     const filterValue = (event.target as HTMLInputElement).value;
77:     this.dataSource.filter = filterValue.trim().toLowerCase();
78:   }
79: 
80:   guardarAgrupacion() {
81:     if (this.formAgrupacion.valid && this.facultadId) {
82:       let postAgrupacionEspacios = new AgrupacionEspacios();
83:       postAgrupacionEspacios.nombre = this.formAgrupacion.get('nombre')!.value ?? '';
84:       postAgrupacionEspacios.codigo_abreviacion = this.formAgrupacion.get('codigo_abreviacion')!.value ?? '';
85:       postAgrupacionEspacios.descripcion = this.formAgrupacion.get('descripcion')!.value ?? '';
86:       postAgrupacionEspacios.color_hex = this.formAgrupacion.get('color_hex')!.value ?? '';
87:       postAgrupacionEspacios.facultad_id = Number(this.facultadId);
88:       this.espaciosAcademicosService.post('agrupacion-espacios', postAgrupacionEspacios).subscribe((resp: any) => {
89:         this.formAgrupacion.reset();
90:         this.agrupacionEspacios.push(resp.Data);
91:         this.popUpManager.showSuccessAlert(this.translate.instant('espacios_academicos.agregar_agrupacion_ok'))
92:         this.router.navigate(['/']);
93:       }, (error) => {
94:         console.warn(error);
95:         this.popUpManager.showErrorAlert(this.translate.instant('espacios_academicos.agregar_agrupacion_fail'))
96:       });
97:     } else {
98:       this.formAgrupacion.markAllAsTouched();
99:     }
100:   }
101: }

