22:   observaciones!: string;
23:   nombreEvaluador!: string;
24:   planEstudio!: PlanEstudio;
25: 
26:   constructor(
27:     public dialogRef: MatDialogRef<DialogVerObservacionComponent>,
28:     public dialog: MatDialog,
29:     private planEstudiosService: PlanEstudiosService,
30:     private builder: FormBuilder,
31:     private translate: TranslateService,
32:     private popUpManager: PopUpManager,
33:     private terceroService: TercerosService,
34:     @Inject(MAT_DIALOG_DATA) private data: any,
35:   ) {
36:     this.data = data;
37:     this.revisionForm = this.builder.group({
38:       'estadoSeleccionado': ['', Validators.required],
39:       'observaciones': [''],
40:       'nombreEvaluador': [''],
41:       'rolSeleccionado': ['', Validators.required]
42:     });
43:   }
44: 
45:   ngOnInit() {
46:     this.loadTerceroData().then((terceroData) => {
47:       this.revisionForm.get('nombreEvaluador')!.setValue(terceroData.NombreCompleto);
48:     });
49: 
50:     this.getPlanEstudioById(this.data.planEstudioId).then((planEstudio) => {
51:       this.planEstudio = planEstudio;
52:       if (this.planEstudio.Observacion != null && this.planEstudio.Observacion != "") {
53:         this.revisionForm.get('observaciones')!.setValue(this.planEstudio.Observacion);
54:       }
55: 
56:       if (this.planEstudio.EstadoAprobacionId != null) {
57:         let estado = this.data.estadosAprobacion.find(
58:           (estado: any) => estado.Id == this.planEstudio.EstadoAprobacionId.Id
59:         );
60:         this.revisionForm.get('estadoSeleccionado')!.setValue(estado.Nombre);
61:       }
62: 
63:       if (this.planEstudio.RevisorRol != null && this.planEstudio.RevisorRol != "") {
64:         this.rolSeleccionado = this.planEstudio.RevisorRol;
65:         this.revisionForm.get('rolSeleccionado')!.setValue(this.planEstudio.RevisorRol);
66:       }
67:     }).catch((error) => {
68:       this.popUpManager.showPopUpGeneric(
69:         this.translate.instant('GLOBAL.error'),
70:         this.translate.instant('plan_estudios.error_cargando_datos_formulario'),
71:         'error',
72:         false
73:       ).then((action) => {
74:         this.dialogRef.close();
75:       });
76:     });
77:   }
78: 
79:   private async loadTerceroData(): Promise<any> {
80:     return new Promise((resolve, reject) => {
81:       this.terceroService.get(`tercero/${this.data.tercero_id}`).subscribe(
82:         response => {
83:           resolve(response);
84:         },
85:         error => {
86:           reject({"tercero": error});
87:         });
88:     });
89:   }
90: 
91:   private getPlanEstudioById(planEstudioId: number): Promise<any> {
92:     return new Promise((resolve, reject) => {
93:       this.planEstudiosService.get(`plan_estudio/${planEstudioId}`).subscribe(
94:         (response: any) => {
95:           resolve(response.Data);
96:         },
97:         error => {
98:           reject({"planEstudio": error});
99:         });
100:     });
101:   }
102: 
103:   salirObservacion() {
104:     this.dialogRef.close();
105:   }
106: }

