484:   private calcularFechaFinHabiles(desde: Date, dias: number): Date {
485:     const result = new Date(desde.getFullYear(), desde.getMonth(), desde.getDate());
486: 
487:     const startYear = result.getFullYear();
488:     if (!this._festivosCache[startYear]) {
489:       const festivos = this._hd.getHolidays(startYear)
490:         .filter(h => h.type === 'public')
491:         .map(h => h.date.substring(0, 10));
492:       this._festivosCache[startYear] = new Set(festivos);
493:     }
494:     const startKey = `${result.getFullYear()}-${String(result.getMonth() + 1).padStart(2, '0')}-${String(result.getDate()).padStart(2, '0')}`;
495:     let count = this._festivosCache[startYear].has(startKey) ? 0 : 1;
496: 
497:     while (count < dias + 1) {
498:       result.setDate(result.getDate() + 1);
499:       const dow = result.getDay();
500:       if (dow === 0 || dow === 6) continue;
501: 
502:       const year = result.getFullYear();
503:       if (!this._festivosCache[year]) {
504:         const festivos = this._hd.getHolidays(year)
505:           .filter(h => h.type === 'public')
506:           .map(h => h.date.substring(0, 10));
507:         this._festivosCache[year] = new Set(festivos);
508:       }
509: 
510:       const key = `${result.getFullYear()}-${String(result.getMonth() + 1).padStart(2, '0')}-${String(result.getDate()).padStart(2, '0')}`;
511:       if (!this._festivosCache[year].has(key)) count++;
512:     }
513: 
514:     return result;
515:   }
